-- Platform-admin Live Account Test messaging scoped to the selected real agency.
create or replace function public.get_developer_agency_messages_rc1(p_agency_id uuid) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare v_result jsonb; begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED' using errcode='42501'; end if; if not exists(select 1 from public.agencies where id=p_agency_id) then raise exception 'AGENCY_NOT_FOUND'; end if; select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) into v_result from (select m.id,m.channel,m.sender_role,m.body,m.created_at,m.sender_guard_id,m.recipient_guard_id,m.job_id,case when m.sender_role='guard' then coalesce(sg.name,'Guard') when m.sender_role='agency' then coalesce(a.name,'Agency') else 'Co Pilot' end sender_name,case when m.job_id is not null then coalesce(j.title,m.channel) else m.channel end context,rg.name recipient_name from public.agency_messages m left join public.guards sg on sg.id=m.sender_guard_id left join public.guards rg on rg.id=m.recipient_guard_id left join public.agencies a on a.id=m.agency_id left join public.marketplace_jobs j on j.id=m.job_id where m.agency_id=p_agency_id order by m.created_at desc limit 80)x; return v_result; end $$;
create or replace function public.send_developer_agency_message_rc1(p_agency_id uuid,p_channel text,p_body text,p_job_id uuid default null,p_recipient_guard_id uuid default null) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare v_msg public.agency_messages; begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED' using errcode='42501'; end if; if nullif(trim(p_body),'') is null then raise exception 'MESSAGE_REQUIRED'; end if; if p_channel not in ('all_guards','active_mission','post_job') then raise exception 'INVALID_CHANNEL'; end if; if not exists(select 1 from public.agencies where id=p_agency_id) then raise exception 'AGENCY_NOT_FOUND'; end if; if p_recipient_guard_id is not null and not exists(select 1 from public.guards where id=p_recipient_guard_id and agency_id=p_agency_id) then raise exception 'MESSAGE_GUARD_NOT_IN_AGENCY' using errcode='42501'; end if; if p_job_id is not null and not exists(select 1 from public.marketplace_jobs where id=p_job_id and accepted_agency_id=p_agency_id) then raise exception 'MESSAGE_JOB_NOT_IN_AGENCY' using errcode='42501'; end if; insert into public.agency_messages(agency_id,job_id,sender_user_id,sender_guard_id,recipient_guard_id,sender_role,channel,body) values(p_agency_id,p_job_id,auth.uid(),null,p_recipient_guard_id,'agency',p_channel,trim(p_body)) returning * into v_msg; return to_jsonb(v_msg)||jsonb_build_object('sender_name',(select name from public.agencies where id=p_agency_id),'context',coalesce((select title from public.marketplace_jobs where id=p_job_id),p_channel),'recipient_name',(select name from public.guards where id=p_recipient_guard_id)); end $$;
revoke all on function public.get_developer_agency_messages_rc1(uuid) from public,anon;
revoke all on function public.send_developer_agency_message_rc1(uuid,text,text,uuid,uuid) from public,anon;
grant execute on function public.get_developer_agency_messages_rc1(uuid) to authenticated,service_role;
grant execute on function public.send_developer_agency_message_rc1(uuid,text,text,uuid,uuid) to authenticated,service_role;
